examples.setup:
_r = np.random.default_rng(5)
X = _r.normal(size=(8, 3)); Y = np.array([0, 1, 2, 1, 0, 2, 2, 1])
P = {'W1': _r.normal(size=(3, 6)) * 0.5, 'b1': _r.normal(size=6) * 0.1, 'W2': _r.normal(size=(6, 3)) * 0.5, 'b2': np.zeros(3)}
def _loss(Q):
    z = np.maximum(X @ Q['W1'] + Q['b1'], 0) @ Q['W2'] + Q['b2']
    m = z.max(axis=1, keepdims=True)
    return float(np.mean(m[:, 0] + np.log(np.exp(z - m).sum(axis=1)) - z[np.arange(8), Y]))
def _step_ok(names):
    new, _ = mlp_train_step({k: v.copy() for k, v in P.items()}, X, Y, 0.1)
    worst = 0.0
    for k in names:
        g = (P[k] - new[k]) / 0.1
        for i in np.ndindex(P[k].shape):
            A = {n: v.copy() for n, v in P.items()}; A[k][i] += 1e-6
            Bq = {n: v.copy() for n, v in P.items()}; Bq[k][i] -= 1e-6
            n_ = (_loss(A) - _loss(Bq)) / 2e-6
            worst = max(worst, abs(n_ - g[i]) / max(1e-3, abs(n_)))
    return worst < 1e-5
def _run(n):
    Q = {k: v.copy() for k, v in P.items()}
    for _ in range(n):
        Q, _l = mlp_train_step(Q, X, Y, 0.5)
    return _loss(Q)

